def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'
    if n == 3:
        return 'D'
    if n == 4:
        if history[3][1] == 'D':
            return 'D'
        return 'C'
    if n == 99:
        return 'D'

    opp_C = 0
    for h in history:
        if h[1] == 'C':
            opp_C += 1
    opp_D = n - opp_C

    if opp_C == 0:
        return 'D'
    if opp_D == 0:
        return 'D'

    last_opp = history[-1][1]
    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'C'
    else:
        last_my = history[-1][0]
        if last_my == 'D':
            return 'D'
        return 'C'
